sys_script_include.script:
var HoCOHSMPdfGeneration = Class.create();
HoCOHSMPdfGeneration.prototype = {
    initialize: function() {
    },

	//This function will generate a PDF and attach it to a record from the Hoc Investigation Table.
	//Param 1: Current object of the record (Mandatory)
	//Param 2: Sys_ID of the HR PDF template you want to use. If not provided, if will use the one stored in the field pdf_template of the record (Optional)
	//Param 3: File name. If provided, will change the name of the PDF being generated. If not provided, it will take the same name as the template being used.
	//Here's a few examples of how to call the function:
		//new x_hccc_hoc_ohs.HoCOHSMPdfGeneration().generatePDF(current); - Use default behavior (Template defined in pdf_template, and the file will be named like the PDF Template being used)
		//new x_hccc_hoc_ohs.HoCOHSMPdfGeneration().generatePDF(current, null, "myNewPDFName.pdf"); - Change the file name
		//new x_hccc_hoc_ohs.HoCOHSMPdfGeneration().generatePDF(current, "a901c93887153c10b7cac956cebb353f"); //Change de PDF Template
		//new x_hccc_hoc_ohs.HoCOHSMPdfGeneration().generatePDF(current, "a901c93887153c10b7cac956cebb353f", "myNewPDFName.pdf"); - Change both the file name and the PDF template
	generatePDF: function(current, pdf_template, fileName) { //Only file name is not mandatory
	if (!current || !pdf_template){
		gs.info("Error in x_hccc_hoc_ohs.HoCOHSMPdfGeneration - either current or pdf_template is null");
		return;
	}
	var gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
	//If a case exist with the type "PDF Generation", the parent is the current case's sys_id and with the pdf_template we want
    gr.addEncodedQuery('hr_service=ade54b651b04a9149fde86acdd4bcbb2^parent=' + current.sys_id + '^pdf_template=' + pdf_template);
    gr.setLimit(1);
    gr.query();

	var pdf_generator_sys_id = ""; //Will contain the sys_id of the child case ("PDF Generation" case)
    if (gr.hasNext()) {
		//IF YES, Retrieve this subcase sys_id, subcase = <retrieved sys_id>
		pdf_generator_sys_id = current.getValue('sys_id');
    }
	else
	{
      //var gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
		gr.initialize();
		var fields = current.getFields();
		for (var i = 0; i < fields.size(); i++) {
			var glideElement = fields.get(i);
			var key = glideElement.getName();
			if(glideElement.getName() != 'sys_id') //Make sure we don't copy the sys_id
			{
				gr[key] = current.getValue(glideElement.getName());                  
			}
		}
		gr.hr_service="ade54b651b04a9149fde86acdd4bcbb2"; //HR Service is getting replaced by "PDF Generation"
		gr.pdf_template= pdf_template;
		gr.parent = current.sys_id;
		//gr.number = "";

      pdf_generator_sys_id = gr.insert();
	}

		//TODO: After the PDF generation, make sure the files gets moved to the parent case. Already a business rule for that?

		//If no pdf_template is defined in the parameter, use the pdf_template of the case
		var pdf_template_sys_id = pdf_template;
		if (new sn_hr_core.hr_PdfUtils().isValidPdfTemplateForPreFill(pdf_template_sys_id)) {
			var pdfDraftSysId = new sn_hr_core.hr_PdfUtils().prefillPdfTemplate(pdf_template_sys_id, false, pdf_generator_sys_id, current.sys_class_name, pdf_generator_sys_id);
			var gr_att = new GlideRecord('sys_attachment');
			gr_att.get(pdfDraftSysId);
			gr_att.query();
			var copyAtt = new GlideSysAttachment();
			copyAtt.copy("pdf_draft", gr_att.table_sys_id+"", "x_hccc_hoc_ohs_investigation_case", gr_att.u_fpc_record.document+"");
			if (gs.nil(pdfDraftSysId))
				gs.addErrorMessage("An error has occured during the PDF creation. Please try again or contact the helpdesk");
						if (fileName){

				//Will rename the last element with the new name
				var attachment = new GlideSysAttachment();
				var agr = attachment.getAttachments('x_hccc_hoc_ohs_investigation_case', current.sys_id);
				while(agr.next()){
					if (agr.hasNext() == false){
						agr.file_name = fileName;
						agr.update();
					  } //End if
				} //End while
			}//End if
		} else {
			gs.addErrorMessage("The template to create the PDF is defective. Please contact the helpdesk");
		}
	},
    type: 'HoCOHSMPdfGeneration'
};
